; Double Dragon 3 (U) - sound driver (Source engine, version 2) and data
; Generated by tools/gen_src.py. Assembles byte-identical with RGBDS 1.0.0.

INCLUDE "hardware.inc"
DEF SRC_VER EQU 2
INCLUDE "source_sound.inc"

DEF wSndVolume             EQU $C000	; high nibble OR-added to every NRx2 low nibble; game sets $F0
DEF wSndV1State            EQU $C001	; voice 1 (ch1): 0 = sounding, $FF = idle
DEF wSndV1EnvPtr           EQU $C002
DEF wSndV1EnvDelta         EQU $C004
DEF wSndV1EnvCount         EQU $C005
DEF wSndV1EnvRate          EQU $C006
DEF wSndV1EnvTimer         EQU $C007
DEF wSndV1FreqLo           EQU $C008
DEF wSndV1FreqHi           EQU $C009
DEF wSndV1Dur              EQU $C00A
DEF wSndV2State            EQU $C00B	; voice 2 (ch2)
DEF wSndV2EnvPtr           EQU $C00C
DEF wSndV2EnvDelta         EQU $C00E
DEF wSndV2EnvCount         EQU $C00F
DEF wSndV2EnvRate          EQU $C010
DEF wSndV2EnvTimer         EQU $C011
DEF wSndV2FreqLo           EQU $C012
DEF wSndV2FreqHi           EQU $C013
DEF wSndV2Dur              EQU $C014
DEF wSndV4State            EQU $C015	; voice 4 (ch4): $80 sounding, $FF idle
DEF wSndV4Dur              EQU $C016
DEF wSndPan                EQU $C017	; Play: NR51 bits (c)
DEF wSndFreqLo             EQU $C018
DEF wSndFreqHi             EQU $C019
DEF wSndDuration           EQU $C01A	; Play: length code 1-6, scaled to frames by DdDurTable
DEF wSndGate1              EQU $C01B	; last note byte per sequencer channel; 0 = rest
DEF wSndGate2              EQU $C01C
DEF wSndGate4              EQU $C01D	; stored, never read
DEF wSndTempo              EQU $C01E	; DdDurTable row; game sets 4
DEF wMusPtr1               EQU $C01F	; sequencer pointers
DEF wMusPtr2               EQU $C021
DEF wMusPtr4               EQU $C023
DEF wMusSong               EQU $C025	; $FF = none
DEF wMusPlaying            EQU $C026	; DdSnd_Update runs the sequencer while nonzero

SECTION "DD3 sound driver", ROM0[$3AD2]

; Song = (ch2, ch1, ch4) sequences in bank 7. The game maps bank 7 before
; calling the driver.
DdSongTable:
	dw DdSong0_Ch2, DdSong0_Ch1, DdSong0_Ch4	; 0
	dw DdSong1_Ch2, DdSong1_Ch1, DdSong1_Ch4	; 1
	dw DdSong2_Ch2, DdSong2_Ch1, DdSong2_Ch4	; 2
	dw DdSong3_Ch2, DdSong3_Ch1, DdSong3_Ch4	; 3
	dw DdSong4_Ch2, DdSong4_Ch1, DdSong4_Ch4	; 4
	dw DdSong5_Ch2, DdSong5_Ch1, DdSong5_Ch4	; 5
	dw DdSong6_Ch2, DdSong6_Ch1, DdSong6_Ch4	; 6

DdEnv_Hold:
	env_step 0, 1, 255
	env_end

DdSnd_Update:
	ld a,[wMusPlaying]	; game calls this every frame (bank 7 mapped)
	or a
	jr z, .voices
	call DdSnd_Sequencer
.voices:
	jp DdSnd_Voices

DdInstTable:
	dw DdInst_Pulse1, DdInst_Pulse2, DdInst_Pulse2, DdInst_Pulse2, DdInst_Noise, DdInst_Noise, DdInst_Noise, DdInst_Noise, DdInst_Noise
DdInst_Pulse1:	inst_pulse1 $40, $F1, DdEnv_Hold
DdInst_Pulse2:	inst_pulse2 $80, $C2, DdEnv_Hold
DdInst_Noise:	; inst_noise $A1, $21 - its NR43 byte is the first byte of DdDurTable
	db 4, $A1

; Length code (1-6) -> frames, one row of 8 per tempo (wSndTempo). Row r gives
; 1x 2x 3x 4x 6x 8x of (r+3) frames. The game always uses row 4 (7 frames).
DdDurTable:
	db $21, $03, $06, $09, $0C, $12, $18, $00	; tempo 0
	db $00, $04, $08, $0C, $10, $18, $20, $00	; tempo 1
	db $00, $05, $0A, $0F, $14, $1E, $28, $00	; tempo 2
	db $00, $06, $0C, $12, $18, $24, $30, $00	; tempo 3
	db $00, $07, $0E, $15, $1C, $2A, $38, $00	; tempo 4
	db $00, $08, $10, $18, $20, $30, $40, $00	; tempo 5
	db $00, $09, $12, $1B, $24, $36, $48, $00	; tempo 6
	db $00, $0A, $14, $1E, $28, $3C, $50, $00	; tempo 7
	db $00	; unused

DdSnd_Play:
	push af	; a = note index, b = instrument, c = NR51 bits, [wSndDuration] = length code
	push de
	ld hl,DdDurTable
	ld a,[wSndTempo]
	add a,a
	add a,a
	add a,a
	ld d,$00
	ld e,a
	ld a,[wSndDuration]
	add a,e
	ld e,a
	add hl,de
	ld a,[hl]
	ld [wSndDuration],a
	pop de
	ld a,c
	ld [wSndPan],a
	pop af
	cp $B8	; ch4 rest ($00 - $48)
	jr z, .rest
	cp $DC	; ch1/ch2 rest ($00 - $24)
	jr z, .rest
	cp $DC	; (same test twice)
	jr nz, .lookup
.rest:
	ld a,$FF
	ld de,$0000
.lookup:
	cp $FF
	jr z, .setFreq
	add a,a
	ld h,$00
	ld l,a
	ld de,DdFreqTable
	add hl,de
	ld e,[hl]
	inc hl
	ld d,[hl]
.setFreq:
	ld a,e
	ld [wSndFreqLo],a
	ld a,d
	and $07
	ld [wSndFreqHi],a
	ld a,$FF
	ldh [rNR50],a
	ld h,$00
	ld l,b
	add hl,hl
	ld de,DdInstTable
	add hl,de
	ld a,[hli]
	ld h,[hl]
	ld l,a
	ld a,[hli]
	cp $02
	jp z, .ch2
	jr c, .ch1
	cp $04
	jp .ch4	; "jp z" in v1; here every type >= 4 goes to ch4
.ch1:
	ld a,[wSndDuration]
	ld [wSndV1Dur],a
	xor a
	ld [wSndV1State],a
	ld a,[wSndGate1]
	or a
	ret z
	ld a,[hli]
	ldh [rNR11],a
	ld a,[hli]
	and $0F	; NRx2 = (inst & $0F) + wSndVolume
	ld c,a
	ld a,[wSndVolume]
	add a,c
	ldh [rNR12],a
	ld c,[hl]
	inc hl
	ld b,[hl]
	ld a,[bc]
	inc bc
	ld [wSndV1EnvDelta],a
	ld a,[bc]
	inc bc
	ld [wSndV1EnvCount],a
	ld a,[bc]
	inc bc
	ld [wSndV1EnvRate],a
	ld [wSndV1EnvTimer],a
	ld a,c
	ld [wSndV1EnvPtr],a
	ld a,b
	ld [wSndV1EnvPtr+1],a
	xor a
	ldh [rNR10],a
	ld a,[wSndFreqLo]
	ldh [rNR13],a
	ld [wSndV1FreqLo],a
	ld a,[wSndPan]
	ld c,a
	ldh a,[rNR51]
	and $EE
	or c
	ldh [rNR51],a
	ldh a,[rNR52]
	or $81
	ldh [rNR52],a
	ld a,[wSndFreqHi]
	ld [wSndV1FreqHi],a
	or $80
	ldh [rNR14],a
	ret
.ch2:
	ld a,[wSndDuration]
	ld [wSndV2Dur],a
	xor a
	ld [wSndV2State],a
	ld a,[wSndGate2]
	or a
	ret z
	ld a,[hli]
	ldh [rNR21],a
	ld a,[hli]
	and $0F
	ld c,a
	ld a,[wSndVolume]
	add a,c
	ldh [rNR22],a
	ld c,[hl]
	inc hl
	ld b,[hl]
	ld a,[bc]
	inc bc
	ld [wSndV2EnvDelta],a
	ld a,[bc]
	inc bc
	ld [wSndV2EnvCount],a
	ld a,[bc]
	inc bc
	ld [wSndV2EnvRate],a
	ld [wSndV2EnvTimer],a
	ld a,c
	ld [wSndV2EnvPtr],a
	ld a,b
	ld [wSndV2EnvPtr+1],a
	ld a,[wSndFreqLo]
	ldh [rNR23],a
	ld [wSndV2FreqLo],a
	ld a,[wSndPan]
	add a,a
	ld c,a
	ldh a,[rNR51]
	and $DD
	or c
	ldh [rNR51],a
	ldh a,[rNR52]
	or $82
	ldh [rNR52],a
	ld a,[wSndFreqHi]
	ld [wSndV2FreqHi],a
	or $80
	ldh [rNR24],a
	ret
.ch4:
	ld a,[wSndFreqLo]
	ld c,a
	ld a,[wSndFreqHi]	; zero frequency (rest) = no hit
	or c
	ret z
	ld a,[wSndDuration]
	ld [wSndV4Dur],a
	ld a,[wSndVolume]
	cp $A0	; wSndVolume >= $A0: raw inst value
	jr nc, .rawVol
	ld c,a
	ld a,[hli]
	and $0F
	add a,c
	ldh [rNR42],a
	jr .nr43
.rawVol:
	ld a,[hli]
	ldh [rNR42],a
.nr43:
	ld a,[hli]
	ldh [rNR43],a
	ld a,[wSndPan]
	add a,a
	add a,a
	add a,a
	ld c,a
	ldh a,[rNR51]
	and $77
	or c
	ldh [rNR51],a
	ldh a,[rNR52]
	or $88
	ldh [rNR52],a
	ld a,$80
	ldh [rNR44],a
	ld [wSndV4State],a
	ret
DdSnd_Voices:
	ld a,[wSndV1State]
	inc a
	jp z, .ch2
	ld a,[wSndV1Dur]
	dec a
	ld [wSndV1Dur],a
	jp z, .ch1Off
	ld a,[wSndGate1]
	or a
	jr nz, .ch1Env
	ldh a,[rNR51]
	and $EE
	ldh [rNR51],a
	ldh a,[rNR52]
	and $FE
	ldh [rNR52],a
	jp .ch2
.ch1Env:
	ld a,[wSndV1EnvTimer]
	dec a
	jr z, .ch1Step
	ld [wSndV1EnvTimer],a
	jr .ch2
.ch1Step:
	ld a,[wSndV1EnvRate]
	ld [wSndV1EnvTimer],a
	ld a,[wSndV1EnvDelta]
	ld c,a
	bit 7,a
	jr z, .ch1Pos
	ld a,[wSndV1FreqLo]
	add a,c
	ld [wSndV1FreqLo],a
	ldh [rNR13],a
	ld a,[wSndV1FreqHi]
	sbc a,$FF
	ld [wSndV1FreqHi],a
	ldh [rNR14],a
	jr .ch1Count
.ch1Pos:
	ld a,[wSndV1FreqLo]
	add a,c
	ld [wSndV1FreqLo],a
	ldh [rNR13],a
	ld a,[wSndV1FreqHi]
	adc a,$00
	ld [wSndV1FreqHi],a
	ldh [rNR14],a
.ch1Count:
	ld a,[wSndV1EnvCount]
	dec a
	jr z, .ch1Next
	ld [wSndV1EnvCount],a
	jr .ch2
.ch1Next:
	ld a,[wSndV1EnvPtr]
	ld l,a
	ld a,[wSndV1EnvPtr+1]
	ld h,a
	ld a,[hli]
	cp $63
	jr z, .ch1Off
	ld [wSndV1EnvDelta],a
	ld a,[hli]
	ld [wSndV1EnvCount],a
	ld a,[hli]
	ld [wSndV1EnvRate],a
	ld [wSndV1EnvTimer],a
	ld a,l
	ld [wSndV1EnvPtr],a
	ld a,h
	ld [wSndV1EnvPtr+1],a
	jr .ch2
.ch1Off:
	ldh a,[rNR51]
	and $EE
	ldh [rNR51],a
	ldh a,[rNR52]
	and $FE
	ldh [rNR52],a
	ld a,$FF
	ld [wSndV1State],a
.ch2:
	ld a,[wSndV2State]
	inc a
	jp z, .ch4
	ld a,[wSndV2Dur]
	dec a
	ld [wSndV2Dur],a
	jp z, .ch2Off
	ld a,[wSndGate2]
	or a
	jr nz, .ch2Env
	jp .ch4
.ch2Env:
	ld a,[wSndV2EnvTimer]
	dec a
	jr z, .ch2Step
	ld [wSndV2EnvTimer],a
	jr .ch4
.ch2Step:
	ld a,[wSndV2EnvRate]
	ld [wSndV2EnvTimer],a
	ld a,[wSndV2EnvDelta]
	ld c,a
	bit 7,a
	jr z, .ch2Pos
	ld a,[wSndV2FreqLo]
	add a,c
	ld [wSndV2FreqLo],a
	ldh [rNR23],a
	ld a,[wSndV2FreqHi]
	sbc a,$FF
	ld [wSndV2FreqHi],a
	ldh [rNR24],a
	jr .ch2Count
.ch2Pos:
	ld a,[wSndV2FreqLo]
	add a,c
	ld [wSndV2FreqLo],a
	ldh [rNR23],a
	ld a,[wSndV2FreqHi]
	adc a,$00
	ld [wSndV2FreqHi],a
	ldh [rNR24],a
.ch2Count:
	ld a,[wSndV2EnvCount]
	dec a
	jr z, .ch2Next
	ld [wSndV2EnvCount],a
	jr .ch4
.ch2Next:
	ld a,[wSndV2EnvPtr]
	ld l,a
	ld a,[wSndV2EnvPtr+1]
	ld h,a
	ld a,[hli]
	cp $63
	jr z, .ch2Off
	ld [wSndV2EnvDelta],a
	ld a,[hli]
	ld [wSndV2EnvCount],a
	ld a,[hli]
	ld [wSndV2EnvRate],a
	ld [wSndV2EnvTimer],a
	ld a,l
	ld [wSndV2EnvPtr],a
	ld a,h
	ld [wSndV2EnvPtr+1],a
	jr .ch4
.ch2Off:
	ldh a,[rNR51]
	and $DD
	ldh [rNR51],a
	ldh a,[rNR52]
	and $FD
	ldh [rNR52],a
	ld a,$FF
	ld [wSndV2State],a
.ch4:
	ld a,[wSndV4State]
	inc a
	ret z
	ld a,[wSndV4Dur]
	dec a
	ld [wSndV4Dur],a
	ret nz
	dec a
	ld [wSndV4State],a
	ldh a,[rNR51]
	and $77
	ldh [rNR51],a
	ldh a,[rNR52]
	and $F7
	ldh [rNR52],a
	ret
DdSnd_PlaySong:
	ld [wMusSong],a
	add a,a
	ld c,a
	add a,a
	add a,c
	ld e,a
	ld d,$00
	ld hl,DdSongTable
	add hl,de
	ld a,[hli]
	ld [wMusPtr2],a
	ld a,[hli]
	ld [wMusPtr2+1],a
	ld a,[hli]
	ld [wMusPtr1],a
	ld a,[hli]
	ld [wMusPtr1+1],a
	ld a,[hli]
	ld [wMusPtr4],a
	ld a,[hli]
	ld [wMusPtr4+1],a
	ld a,$01
	ld [wMusPlaying],a
	ret
DdSnd_Sequencer:
	ld a,[wSndV1State]
	inc a
	jr nz, .ch2
	ld a,[wMusPtr1]
	ld l,a
	ld a,[wMusPtr1+1]
	ld h,a
	ld a,[hli]
	cp $FE	; $FE: restart song
	jp z, DdSnd_LoopSong
	cp $FF	; $FF: stop
	jp z, DdSnd_StopMusic
	ld [wSndGate1],a
	sub $24
	ld c,a
	ld a,[hli]
	ld [wSndDuration],a
	ld a,l
	ld [wMusPtr1],a
	ld a,h
	ld [wMusPtr1+1],a
	ld a,c
	ld bc,$000B	; b = 0 (ch1 inst), c = $0B: ch1+ch2+ch4 right only
	call DdSnd_Play
.ch2:
	ld a,[wSndV2State]
	inc a
	jr nz, .ch4
	ld a,[wMusPtr2]
	ld l,a
	ld a,[wMusPtr2+1]
	ld h,a
	ld a,[hli]
	cp $FE
	jr z, DdSnd_LoopSong
	cp $FF
	jp z, DdSnd_StopMusic
	ld [wSndGate2],a
	sub $24
	ld c,a
	ld a,[hli]
	ld [wSndDuration],a
	ld a,l
	ld [wMusPtr2],a
	ld a,h
	ld [wMusPtr2+1],a
	ld a,c
	ld bc,$0311	; b = 3 (ch2 inst), c = $11
	call DdSnd_Play
.ch4:
	ld a,[wSndV4State]
	inc a
	ret nz
	ld a,[wMusPtr4]
	ld l,a
	ld a,[wMusPtr4+1]
	ld h,a
	ld a,[hli]
	cp $FE
	jr z, DdSnd_LoopSong
	cp $FF
	jp z, DdSnd_StopMusic
	ld [wSndGate4],a
	sub $48
	ld c,a
	ld a,[hli]
	ld [wSndDuration],a
	ld a,l
	ld [wMusPtr4],a
	ld a,h
	ld [wMusPtr4+1],a
	ld a,c
	ld bc,$0811	; b = 8 (drum inst), c = $11
	jp DdSnd_Play
DdSnd_LoopSong:
	ld a,[wMusSong]
	jp DdSnd_PlaySong
DdSnd_StopMusic:
	xor a
	ld [wSndVolume],a
	dec a
	ld [wMusSong],a
	ldh a,[rNR51]
	and $EE
	ldh [rNR51],a
	ldh a,[rNR52]
	and $FE
	ldh [rNR52],a
	ldh a,[rNR51]
	and $DD
	ldh [rNR51],a
	ldh a,[rNR52]
	and $FD
	ldh [rNR52],a
	xor a
	ld [wMusPlaying],a
	ret

; 48 notes, C2-B5
DdFreqTable:
	dw $002C, $009D, $0107, $016B, $01CA, $0223, $0277, $02C7, $0312, $0359, $039B, $03DA
	dw $0416, $044E, $0483, $04B6, $04E5, $0511, $053C, $0563, $0589, $05AC, $05CF, $05ED
	dw $060B, $0627, $0642, $065B, $0672, $0689, $069E, $06B1, $06C4, $06D6, $06E7, $06F6
	dw $0705, $0714, $0721, $072D, $0739, $0744, $074F, $0759, $0762, $076B, $0773, $077B

; SFX 0-4: noise (NR41, NR42, NR43, NR44, unused); SFX 5-8: ch1 (NR10-NR14)
DdSfxTable:
	sfx_noise $00, $F1, $44, $40, $00	; 0
	sfx_noise $00, $A1, $44, $40, $00	; 1
	sfx_noise $00, $F1, $6C, $40, $00	; 2
	sfx_noise $01, $E4, $81, $40, $00	; 3
	sfx_noise $00, $F3, $63, $00, $00	; 4
	sfx_pulse $46, $D4, $F3, $E3, $06	; 5
	sfx_pulse $46, $94, $F3, $E8, $46	; 6
	sfx_pulse $7E, $84, $F2, $30, $07	; 7
	sfx_pulse $76, $85, $FA, $15, $07	; 8

DdSnd_PlaySfx:
	ld c,a
	add a,a
	add a,a
	add a,c
	ld d,$00
	ld e,a
	ld hl,DdSfxTable
	add hl,de
	ld a,c
	cp $05	; SFX 0-4 noise, 5-8 ch1
	jp nc, .pulse
	jp .noise
.pulse:
	ld a,[hli]
	ldh [rNR10],a
	ld a,[hli]
	ldh [rNR11],a
	ld a,[hli]
	ldh [rNR12],a
	ld a,[hli]
	ldh [rNR13],a
	ld a,[$0011]	; BUG: reads ROM $0011 ($CF) instead of ld a,$11
	ld c,a
	ldh a,[rNR51]
	and $EE
	or c
	ldh [rNR51],a
	ldh a,[rNR52]
	or $81
	ldh [rNR52],a
	ld a,[hli]
	or $80
	ldh [rNR14],a
	ret
.noise:
	ld a,[hli]
	ldh [rNR41],a
	ld a,[hli]
	ldh [rNR42],a
	ld a,[hli]
	ldh [rNR43],a
	ld c,$88
	ldh a,[rNR51]
	and $77
	or c
	ldh [rNR51],a
	ld a,$FF
	ldh [rNR50],a
	ldh a,[rNR52]
	or $88
	ldh [rNR52],a
	ld a,[hli]
	or $80
	ldh [rNR44],a
	ret

SECTION "DD3 music", ROMX[$4000], BANK[$07]

; Sequences: note NOTE, len / drum byte, len / rest len (len = code 1-6),
; snd_loop ($FE, restarts the whole song) / snd_end ($FF, stops all music).
DdSong0_Ch4:
	drum $48, 2
	drum $4A, 1
	drum $48, 2
	drum $48, 1
	drum $4A, 2
	drum $48, 2
	drum $4A, 2
	drum $48, 1
	drum $48, 1
	drum $4A, 2
	drum $48, 2
	drum $4A, 1
	drum $48, 2
	drum $48, 1
	drum $4A, 2
	drum $48, 2
	drum $4A, 2
	drum $48, 1
	drum $4A, 2
	drum $4A, 1
	drum $48, 2
	drum $4A, 1
	drum $48, 2
	drum $48, 1
	drum $4A, 2
	drum $48, 2
	drum $4A, 2
	drum $48, 1
	drum $48, 1
	drum $4A, 2
	drum $48, 2
	drum $4A, 1
	drum $48, 2
	drum $48, 1
	drum $4A, 2
	drum $48, 2
	drum $4A, 2
	drum $48, 1
	drum $4A, 2
	drum $4A, 1
	drum $48, 2
	drum $4A, 1
	drum $48, 2
	drum $48, 1
	drum $4A, 2
	drum $48, 2
	drum $4A, 2
	drum $48, 1
	drum $48, 1
	drum $4A, 2
	drum $48, 2
	drum $4A, 1
	drum $48, 2
	drum $48, 1
	drum $4A, 2
	drum $48, 2
	drum $4A, 2
	drum $48, 1
	drum $4A, 2
